-- Additive MerKora project memory schema. No existing tables or rows are modified.
create or replace function public.is_merkora_admin() returns boolean language sql stable security invoker set search_path='' as $$ select lower(coalesce(auth.jwt()->>'email','')) in ('merkelnascom@gmail.com','wdesk87@gmail.com') $$;
revoke all on function public.is_merkora_admin() from public, anon;
grant execute on function public.is_merkora_admin() to authenticated;

create table public.project_memory_brief_versions(id uuid primary key default gen_random_uuid(),project_id text not null references public.user_projects(id) on delete restrict,version integer not null check(version>0),payload jsonb not null check(jsonb_typeof(payload)='object'),payload_digest text not null check(payload_digest~'^[a-f0-9]{64}$'),created_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now(),unique(project_id,version),unique(id,project_id));
create table public.project_memory_plan_versions(id uuid primary key default gen_random_uuid(),project_id text not null references public.user_projects(id) on delete restrict,version integer not null check(version>0),source_brief_version integer not null check(source_brief_version>0),planner_version text not null check(char_length(planner_version) between 1 and 100),payload jsonb not null check(jsonb_typeof(payload)='object'),payload_digest text not null check(payload_digest~'^[a-f0-9]{64}$'),created_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now(),unique(project_id,version),unique(id,project_id),foreign key(project_id,source_brief_version) references public.project_memory_brief_versions(project_id,version) on delete restrict);
create table public.project_memory_decisions(id uuid primary key default gen_random_uuid(),project_id text not null references public.user_projects(id) on delete restrict,brief_version integer,plan_version integer,decision_type text not null check(decision_type in('module_selected','module_rejected','scope_confirmed','clarification_answered','change_requested','other')),decision text not null check(char_length(decision) between 1 and 3000),comment text not null default '' check(char_length(comment)<=2000),actor_user_id uuid not null references auth.users(id) on delete restrict,actor_role text not null check(actor_role in('client','admin')),created_at timestamptz not null default now(),foreign key(project_id,brief_version) references public.project_memory_brief_versions(project_id,version) on delete restrict,foreign key(project_id,plan_version) references public.project_memory_plan_versions(project_id,version) on delete restrict);
create table public.project_memory_approvals(id uuid primary key default gen_random_uuid(),project_id text not null references public.user_projects(id) on delete restrict,plan_version integer not null,approval_kind text not null check(approval_kind in('client_scope','admin_review','execution_authorization')),decision text not null check(decision in('approved','changes_requested')),plan_digest text not null check(plan_digest~'^[a-f0-9]{64}$'),scope_digest text not null check(scope_digest~'^[a-f0-9]{64}$'),actor_user_id uuid not null references auth.users(id) on delete restrict,actor_role text not null check(actor_role in('client','admin')),comment text not null default '' check(char_length(comment)<=2000),request_id uuid not null,created_at timestamptz not null default now(),unique(project_id,request_id),foreign key(project_id,plan_version) references public.project_memory_plan_versions(project_id,version) on delete restrict);
create table public.project_factory_jobs(id uuid primary key default gen_random_uuid(),project_id text not null references public.user_projects(id) on delete restrict,plan_version integer not null,plan_digest text not null check(plan_digest~'^[a-f0-9]{64}$'),scope_digest text not null check(scope_digest~'^[a-f0-9]{64}$'),status text not null default 'queued' check(status in('queued','planning','building','testing','repairing','awaiting_approval','ready','blocked','failed','delivered','interrupted','cancelled')),manifest jsonb not null check(jsonb_typeof(manifest)='object'),requested_by uuid not null references auth.users(id) on delete restrict,authorized_by uuid references auth.users(id) on delete restrict,approval_ids uuid[] not null default '{}',correlation_id uuid not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,project_id),foreign key(project_id,plan_version) references public.project_memory_plan_versions(project_id,version) on delete restrict);
create table public.project_factory_tasks(id uuid primary key default gen_random_uuid(),job_id uuid not null,project_id text not null,task_key text not null check(char_length(task_key) between 1 and 160),state text not null default 'not_started' check(state in('not_started','ready','in_progress','blocked','completed','failed','cancelled')),dependencies jsonb not null default '[]' check(jsonb_typeof(dependencies)='array'),evidence_required boolean not null default false,external_side_effect boolean not null default false,result_is_known boolean not null default true,attempt_count integer not null default 0 check(attempt_count>=0),last_error_safe text not null default '' check(char_length(last_error_safe)<=2000),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(job_id,task_key),unique(id,job_id,project_id),foreign key(job_id,project_id) references public.project_factory_jobs(id,project_id) on delete restrict);
create table public.project_factory_evidence(id uuid primary key default gen_random_uuid(),job_id uuid not null,project_id text not null,task_id uuid,evidence_type text not null check(evidence_type in('test_result','build_log','screenshot','artifact','review','external_state_check','other')),storage_path text not null check(char_length(storage_path) between 1 and 1000),content_digest text check(content_digest is null or content_digest~'^[a-f0-9]{64}$'),metadata jsonb not null default '{}' check(jsonb_typeof(metadata)='object'),created_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now(),foreign key(job_id,project_id) references public.project_factory_jobs(id,project_id) on delete restrict,foreign key(task_id,job_id,project_id) references public.project_factory_tasks(id,job_id,project_id) on delete restrict);
create table public.project_memory_events(id uuid primary key default gen_random_uuid(),project_id text not null references public.user_projects(id) on delete restrict,event_type text not null check(event_type in('brief_version_created','plan_version_created','decision_recorded','approval_recorded','task_started','task_completed','task_blocked','task_failed','job_interrupted','job_resumed','evidence_recorded','delivery_recorded')),actor_user_id uuid references auth.users(id) on delete restrict,actor_role text not null check(actor_role in('client','admin','system')),correlation_id uuid not null,brief_version integer,plan_version integer,task_key text,summary text not null check(char_length(summary) between 1 and 2000),payload jsonb not null default '{}' check(jsonb_typeof(payload)='object'),created_at timestamptz not null default now(),foreign key(project_id,brief_version) references public.project_memory_brief_versions(project_id,version) on delete restrict,foreign key(project_id,plan_version) references public.project_memory_plan_versions(project_id,version) on delete restrict);
create table public.project_resume_snapshots(id uuid primary key default gen_random_uuid(),job_id uuid not null,project_id text not null,snapshot jsonb not null check(jsonb_typeof(snapshot)='object'),snapshot_digest text not null check(snapshot_digest~'^[a-f0-9]{64}$'),generated_by uuid references auth.users(id) on delete restrict,generated_at timestamptz not null default now(),foreign key(job_id,project_id) references public.project_factory_jobs(id,project_id) on delete restrict);

create index project_memory_brief_versions_project_created_idx on public.project_memory_brief_versions(project_id,created_at desc);
create index project_memory_plan_versions_project_created_idx on public.project_memory_plan_versions(project_id,created_at desc);
create index project_memory_decisions_project_created_idx on public.project_memory_decisions(project_id,created_at desc);
create index project_memory_approvals_project_plan_idx on public.project_memory_approvals(project_id,plan_version,created_at desc);
create index project_factory_jobs_project_created_idx on public.project_factory_jobs(project_id,created_at desc);
create index project_factory_tasks_job_state_idx on public.project_factory_tasks(job_id,state);
create index project_factory_evidence_job_created_idx on public.project_factory_evidence(job_id,created_at desc);
create index project_memory_events_project_created_idx on public.project_memory_events(project_id,created_at desc);
create index project_resume_snapshots_job_created_idx on public.project_resume_snapshots(job_id,generated_at desc);

alter table public.project_memory_brief_versions enable row level security;
alter table public.project_memory_plan_versions enable row level security;
alter table public.project_memory_decisions enable row level security;
alter table public.project_memory_approvals enable row level security;
alter table public.project_factory_jobs enable row level security;
alter table public.project_factory_tasks enable row level security;
alter table public.project_factory_evidence enable row level security;
alter table public.project_memory_events enable row level security;
alter table public.project_resume_snapshots enable row level security;

revoke all on public.project_memory_brief_versions,public.project_memory_plan_versions,public.project_memory_decisions,public.project_memory_approvals,public.project_factory_jobs,public.project_factory_tasks,public.project_factory_evidence,public.project_memory_events,public.project_resume_snapshots from anon,authenticated;
grant select,insert on public.project_memory_brief_versions,public.project_memory_decisions,public.project_memory_approvals to authenticated;
grant select on public.project_memory_plan_versions,public.project_factory_jobs,public.project_factory_tasks,public.project_factory_evidence,public.project_memory_events to authenticated;
grant select,insert,update on public.project_factory_jobs,public.project_factory_tasks to authenticated;
grant select,insert on public.project_memory_plan_versions,public.project_factory_evidence,public.project_memory_events,public.project_resume_snapshots to authenticated;
grant all on public.project_memory_brief_versions,public.project_memory_plan_versions,public.project_memory_decisions,public.project_memory_approvals,public.project_factory_jobs,public.project_factory_tasks,public.project_factory_evidence,public.project_memory_events,public.project_resume_snapshots to service_role;

create policy "project memory brief versions readable by owner or admin" on public.project_memory_brief_versions for select to authenticated using(public.is_merkora_admin() or exists(select 1 from public.user_projects p where p.id=project_id and p.user_id=(select auth.uid())));
create policy "project owner or admin can add brief versions" on public.project_memory_brief_versions for insert to authenticated with check((created_by=(select auth.uid()) and exists(select 1 from public.user_projects p where p.id=project_id and p.user_id=(select auth.uid()))) or(public.is_merkora_admin() and created_by=(select auth.uid())));
create policy "project plans readable by owner or admin" on public.project_memory_plan_versions for select to authenticated using(public.is_merkora_admin() or exists(select 1 from public.user_projects p where p.id=project_id and p.user_id=(select auth.uid())));
create policy "admins can add plan versions" on public.project_memory_plan_versions for insert to authenticated with check(public.is_merkora_admin() and created_by=(select auth.uid()));
create policy "project decisions readable by owner or admin" on public.project_memory_decisions for select to authenticated using(public.is_merkora_admin() or exists(select 1 from public.user_projects p where p.id=project_id and p.user_id=(select auth.uid())));
create policy "project owner can record own client decisions" on public.project_memory_decisions for insert to authenticated with check(actor_user_id=(select auth.uid()) and actor_role='client' and exists(select 1 from public.user_projects p where p.id=project_id and p.user_id=(select auth.uid())));
create policy "project approvals readable by owner or admin" on public.project_memory_approvals for select to authenticated using(public.is_merkora_admin() or exists(select 1 from public.user_projects p where p.id=project_id and p.user_id=(select auth.uid())));
create policy "client can approve exact scope of own project plan" on public.project_memory_approvals for insert to authenticated with check(actor_user_id=(select auth.uid()) and actor_role='client' and approval_kind='client_scope' and exists(select 1 from public.user_projects p where p.id=project_id and p.user_id=(select auth.uid())) and exists(select 1 from public.project_memory_plan_versions v where v.project_id=project_id and v.version=plan_version and v.payload_digest=plan_digest));
create policy "admins can record plan reviews and execution approvals" on public.project_memory_approvals for insert to authenticated with check(public.is_merkora_admin() and actor_user_id=(select auth.uid()) and actor_role='admin');
create policy "factory jobs readable by owner or admin" on public.project_factory_jobs for select to authenticated using(public.is_merkora_admin() or exists(select 1 from public.user_projects p where p.id=project_id and p.user_id=(select auth.uid())));
create policy "admins can create factory jobs" on public.project_factory_jobs for insert to authenticated with check(public.is_merkora_admin() and requested_by=(select auth.uid()));
create policy "admins can update factory jobs" on public.project_factory_jobs for update to authenticated using(public.is_merkora_admin()) with check(public.is_merkora_admin());
create policy "factory tasks readable by owner or admin" on public.project_factory_tasks for select to authenticated using(public.is_merkora_admin() or exists(select 1 from public.user_projects p where p.id=project_id and p.user_id=(select auth.uid())));
create policy "admins can create factory tasks" on public.project_factory_tasks for insert to authenticated with check(public.is_merkora_admin());
create policy "admins can update factory tasks" on public.project_factory_tasks for update to authenticated using(public.is_merkora_admin()) with check(public.is_merkora_admin());
create policy "factory evidence readable by owner or admin" on public.project_factory_evidence for select to authenticated using(public.is_merkora_admin() or exists(select 1 from public.user_projects p where p.id=project_id and p.user_id=(select auth.uid())));
create policy "admins can add factory evidence" on public.project_factory_evidence for insert to authenticated with check(public.is_merkora_admin() and created_by=(select auth.uid()));
create policy "project memory events readable by owner or admin" on public.project_memory_events for select to authenticated using(public.is_merkora_admin() or exists(select 1 from public.user_projects p where p.id=project_id and p.user_id=(select auth.uid())));
create policy "admins can append project memory events" on public.project_memory_events for insert to authenticated with check(public.is_merkora_admin() and(actor_user_id is null or actor_user_id=(select auth.uid())));
create policy "admins can read project resume snapshots" on public.project_resume_snapshots for select to authenticated using(public.is_merkora_admin());
create policy "admins can append project resume snapshots" on public.project_resume_snapshots for insert to authenticated with check(public.is_merkora_admin() and generated_by=(select auth.uid()));

comment on table public.project_memory_brief_versions is 'Append-only immutable brief versions; payload digest computed by trusted server code.';
comment on table public.project_memory_plan_versions is 'Append-only plan versions linked to the exact source brief version.';
comment on table public.project_memory_decisions is 'Append-only project decisions; AI proposals are not client decisions.';
comment on table public.project_memory_approvals is 'Append-only approvals tied to an exact plan digest and scope digest.';
comment on table public.project_factory_jobs is 'Bounded factory execution records; creating a row does not imply a worker or deployment.';
comment on table public.project_factory_tasks is 'Factory task state and resumability metadata; updates restricted to administrators.';
comment on table public.project_factory_evidence is 'Private evidence metadata; artifact bytes require a separately secured storage bucket.';
comment on table public.project_memory_events is 'Append-only project audit events; source records remain authoritative.';
comment on table public.project_resume_snapshots is 'Administrator-only derived resume snapshots; reconstructable from source records.';
